import os
import torch


class Config:
    """
    Centralized configuration for the HuBMAP FTU detection pipeline.
    """

    # --- System Settings ---
    SEED = 42
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    # Use available CPUs but cap at a reasonable number for dataloading overhead
    NUM_WORKERS = min(12, os.cpu_count() if os.cpu_count() else 4)

    # --- File Paths ---
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working/idea_1"
    SUBMISSION_DIR = "./submission"

    # Metadata Files (Generated by metadata script)
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train_metadata.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val_metadata.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test_metadata.csv")

    # Output Files
    MODEL_CHECKPOINT_PATH = os.path.join(WORKING_DIR, "best_model.pth")
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # --- Data Processing Parameters ---
    TILE_SIZE = 1024
    # Overlap for inference sliding window (25% overlap)
    INFERENCE_OVERLAP = 0.25

    # --- Model Architecture ---
    # Using LinkNet with ResNet18 as per the baseline strategy
    ARCH = "linknet"
    ENCODER_NAME = "resnet34"
    ENCODER_WEIGHTS = "imagenet"
    IN_CHANNELS = 3
    CLASSES = 1
    ACTIVATION = None  # Logits returned, handled by loss function with sigmoid

    # --- Training Hyperparameters ---
    # Increased batch size for A100 (40GB)
    BATCH_SIZE = 16
    EPOCHS = 30
    LEARNING_RATE = 2e-4
    WEIGHT_DECAY = 1e-2

    # Early Stopping
    EARLY_STOPPING_PATIENCE = 7
    EARLY_STOPPING_MIN_DELTA = 1e-4

    # --- Post-Processing ---
    THRESHOLD = 0.5
    MIN_PIXEL_SIZE = 0  # Optional: remove small connected components

    # --- Debugging / Development ---
    # Set DEBUG to True to run on a small subset of data for quick testing
    DEBUG = False
    DEBUG_SAMPLE_SIZE = 50  # Number of samples to use in debug mode

    @classmethod
    def setup(cls):
        """
        Ensures that the working and submission directories exist.
        """
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)

    @classmethod
    def get_config_hash(cls):
        """
        Generates a hash based on configuration parameters that affect data generation.
        """
        import hashlib
        import json

        config_dict = {
            "tile_size": cls.TILE_SIZE,
            "overlap_train": 0.0,  # Train/Val always 0 overlap in this pipeline
            "overlap_test": cls.INFERENCE_OVERLAP,
            "seed": cls.SEED,
            "encoder": cls.ENCODER_NAME,
        }
        return hashlib.md5(
            json.dumps(config_dict, sort_keys=True).encode()
        ).hexdigest()[:8]


# Initialize directories upon module import
Config.setup()
